// ═══════════════════════════════════════════════════════════════
//  SISTEMA DE AUTO-ACTUALIZACIÓN — NUNCA PIERDE HERRAMIENTAS
// ═══════════════════════════════════════════════════════════════

(function() {
  'use strict';

  var ultimaActualizacion = 0;

  // 🔑 Firma del catálogo actual. Detecta CUALQUIER cambio (altas, bajas
  //    y ediciones), no solo que haya "más herramientas" que antes.
  function firma(arr) {
    if (!Array.isArray(arr)) return '';
    // Orden estable por id para que el orden de la lista no afecte la firma.
    var ids = arr.map(function(h) { return h && h.id ? String(h.id) : ''; }).sort();
    var base = arr.length + '|' + ids.join(',') + '|' + JSON.stringify(arr);
    // Hash compacto (djb2) para no comparar cadenas enormes.
    var hash = 5381;
    for (var i = 0; i < base.length; i++) {
      hash = ((hash << 5) + hash + base.charCodeAt(i)) | 0;
    }
    return arr.length + ':' + (hash >>> 0).toString(36);
  }

  var firmaActual = firma(herramientasIA);

  // Intenta cada fuente en orden hasta que una responda con un array válido.
  function pedirDatos(fuentes, ahora) {
    if (!fuentes.length) return Promise.reject(new Error('sin fuentes'));
    var url = fuentes[0];
    var sep = url.indexOf('?') === -1 ? '?' : '&';
    return fetch(url + sep + 't=' + ahora, { cache: 'no-store' })
      .then(function(r) {
        if (!r.ok) throw new Error('HTTP ' + r.status);
        return r.json();
      })
      .then(function(datos) {
        if (!Array.isArray(datos) || datos.length === 0) throw new Error('vacio');
        return { datos: datos, fuente: url };
      })
      .catch(function() {
        return pedirDatos(fuentes.slice(1), ahora); // siguiente fuente
      });
  }

  function aplicar(datos, fuente) {
    var nueva = firma(datos);
    if (nueva === firmaActual) {
      console.log('🧭 Sin novedades (' + fuente + '). ' + herramientasIA.length + ' herramientas.');
      return;
    }
    herramientasIA.length = 0;
    datos.forEach(function(h) { herramientasIA.push(h); });
    firmaActual = nueva;
    console.log('🧭 Catálogo actualizado desde ' + fuente + ': ' + herramientasIA.length + ' herramientas.');

    if (typeof window.dispatchEvent === 'function') {
      window.dispatchEvent(new CustomEvent('herramientasActualizadas', { detail: herramientasIA }));
    }
    var c = document.getElementById('contador-footer');
    if (c) c.textContent = herramientasIA.length;
  }

  function actualizar() {
    var ahora = Date.now();
    if ((ahora - ultimaActualizacion) < INTERVALO_ACTUALIZACION) return;
    ultimaActualizacion = ahora;
    console.log('🧭 Buscando actualizaciones...');

    pedirDatos(FUENTES_DATOS.slice(), ahora)
      .then(function(res) { aplicar(res.datos, res.fuente); })
      .catch(function() {
        console.log('🧭 Sin conexión a las fuentes. Usando datos embebidos (' + herramientasIA.length + ' herramientas).');
      });
  }

  // ─── Iniciar ──────────────────────────────────────────
  console.log('🧭 Viaje a Ítaca: ' + herramientasIA.length + ' herramientas.');
  console.log('   Auto-actualización cada ' + (INTERVALO_ACTUALIZACION/60000) + ' min.');

  // Primera actualización a los 5 segundos (deja que la página cargue).
  // La primera vez forzamos la comprobación ignorando el intervalo.
  setTimeout(function() { ultimaActualizacion = 0; actualizar(); }, 5000);

  // Luego cada INTERVALO
  setInterval(actualizar, INTERVALO_ACTUALIZACION);

  // Mostrar contador
  var contador = document.getElementById('contador-footer');
  if (contador) contador.textContent = herramientasIA.length;
})();